package stateoftictactoe

import (
	"errors"
	"strings"
)

type State string

const (
	Win     State = "win"
	Ongoing State = "ongoing"
	Draw    State = "draw"
)

func StateOfTicTacToe(board []string) (State, error) {
	var xWin int
	var oWin int

	rows := board
	cols := getCols(board)
	diags := getDiags(board)
	xCount := count("X", rows)
	oCount := count("O", rows)
	if oCount > xCount {
		return "", errors.New("wrong turn order: O started")
	}
	if xCount > oCount+1 {
		return "", errors.New("wrong turn order: X went twice")
	}

	allCombos := rows
	allCombos = append(allCombos, cols...)
	allCombos = append(allCombos, diags...)

	for _, row := range allCombos {
		if row == "XXX" {
			if xWin > 1 || oWin > 0 {
				return "", errors.New("impossible board: game should have ended after the game was won")
			}
			xWin += 1
		}
		if row == "OOO" {
			if xWin > 0 || oWin > 0 {
				return "", errors.New("impossible board: game should have ended after the game was won")
			}
			oWin = 1
		}
	}

	if xWin > 0 || oWin > 0 {
		return Win, nil
	}

	if xCount+oCount < 9 {
		return Ongoing, nil
	}

	return Draw, nil
}

func getCols(board []string) []string {
	cols := make([]string, 3)
	for _, row := range board {
		for j := 0; j < 3; j++ {
			cols[j] += string(row[j])
		}
	}
	return cols
}

func getDiags(board []string) []string {
	diags := make([]string, 2)
	for i, row := range board {
		diags[0] += string(row[i])
		diags[1] += string(row[2-i])
	}
	return diags
}

func count(c string, rows []string) int {
	num := 0
	for _, row := range rows {
		num += strings.Count(row, c)
	}
	return num
}

